void AGOSEngine::renderStringAmiga(uint vgaSpriteId, uint color, uint width, uint height, const char *txt) {
	VgaPointersEntry *vpe = &_vgaBufferPointers[2];
	byte *p, *dst, *dst_org, chr;
	uint count;

	if (vgaSpriteId >= 100) {
		vgaSpriteId -= 100;
		vpe++;
	}

	dst = vpe->vgaFile2;

	count = 2000;
	if (vgaSpriteId == 1)
		count *= 2;

	p = dst + vgaSpriteId * 8;
	WRITE_BE_UINT16(p + 4, height);
	WRITE_BE_UINT16(p + 6, width);
	dst += READ_BE_UINT32(p);

	width /= 8;	// convert width from pixels to bytes

	const byte *imgSrc = nullptr;
	switch (_language) {
	case Common::IT_ITA:
		imgSrc = italian_simon1AGAFontData;
		break;
	case Common::FR_FRA:
		imgSrc = french_simon1AGAFontData;
		break;
	case Common::DE_DEU:
		imgSrc = german_simon1AGAFontData;
		break;
	case Common::EN_ANY:
		imgSrc = english_simon1AGAFontData;
		break;
	default:
		error("renderStringAmiga: Unknown language %d", _language);
	}


	uint charsize = width * height;
	memset(dst, 0, count);
	dst_org = dst;
	int delta = 0;
	while ((chr = *txt++) != 0) {
		int img_width = 1;
		if (chr == 10) {
			dst += width * 10;
			dst_org = dst;
			delta = 0;
		} else if ((signed char)(chr -= '!') < 0) {
			img_width = 7;
		} else {
			const byte *img = imgSrc + chr * 41;
			img_width = img[40];
			byte *cur_dst = dst_org;
			for (int row = 0; row < 10; row++) {
				int col = color;
				for (int plane = 0; plane < 3; plane++) {
					chr = img[plane] >> delta;
					if (chr) {
						if (col & 1) cur_dst[charsize * 0] |= chr;
						if (col & 2) cur_dst[charsize * 1] |= chr;
						if (col & 4) cur_dst[charsize * 2] |= chr;
						if (col & 8) cur_dst[charsize * 3] |= chr;
					}
					chr = img[plane] << (8 - delta);
					if (((8 - delta) < img_width) && (chr)) {
						if (col & 1) cur_dst[charsize * 0 + 1] |= chr;
						if (col & 2) cur_dst[charsize * 1 + 1] |= chr;
						if (col & 4) cur_dst[charsize * 2 + 1] |= chr;
						if (col & 8) cur_dst[charsize * 3 + 1] |= chr;
					}
					col++;
				}
				chr = img[3] >> delta;
				if (chr) {
					cur_dst[charsize * 0] |= chr;
					cur_dst[charsize * 1] |= chr;
					cur_dst[charsize * 2] |= chr;
					cur_dst[charsize * 3] |= chr;
				}
				chr = img[3] << (8 - delta);
				if (((8 - delta) < img_width) && (chr)) {
					cur_dst[charsize * 0 + 1] |= chr;
					cur_dst[charsize * 1 + 1] |= chr;
					cur_dst[charsize * 2 + 1] |= chr;
					cur_dst[charsize * 3 + 1] |= chr;
				}
				cur_dst += width;
				img += 4;
			}
		}
		delta += img_width - 1;
		if (delta >= 8) {
			delta -= 8;
			dst_org++;
		}
	}
}

// ---------------------------------------------------------------------------
// Acentos pt-BR para a fonte GRAFICA (renderString).
//
// A legenda de fala do Simon 1/2 nao usa os arrays *_simonFont deste arquivo:
// ela e montada a partir de IMAGENS de caractere guardadas na zona VGA 2 do
// proprio SIMON2.GME, indexadas por (caractere - ' '). Essas imagens so cobrem
// o ASCII ingles, entao qualquer codigo acentuado cai no teste
// "img_width == 0 || img_height == 0" e some da tela sem nem ocupar espaco.
//
// Em vez de pedir imagens novas dentro do .GME, desenhamos a LETRA BASE da
// propria fonte do jogo e pintamos o acento por cima - o resultado fica com a
// mesma aparencia do resto do texto.
//
// Os codigos 128..155 sao os mesmos gravados nos arquivos do jogo pelo
// S:\scummvmBR\Simon2\simon2_pt_tool.py (PT_BR_SLOTS). Mudar um exige mudar o
// outro e reimportar a traducao.
// ---------------------------------------------------------------------------

enum PtBrMark {
	kPtBrNone = 0, kPtBrAcute, kPtBrGrave, kPtBrCircumflex,
	kPtBrTilde, kPtBrDiaeresis, kPtBrCedilla
};

static const byte kPtBrFirst = 128;
static const byte kPtBrLast  = 155;

// letra base de cada codigo 128..155
static const char kPtBrBases[] = {
	'a', 'o', 'c', 'a', 'e', 'i', 'o', 'u',   // 128 a~  o~  c,  a'  e'  i'  o'  u'
	'a', 'e', 'o', 'a', 'u',                  // 136 a^  e^  o^  a`  u:
	'A', 'O', 'C', 'A', 'E', 'I', 'O', 'U',   // 141 A~  O~  C,  A'  E'  I'  O'  U'
	'A', 'E', 'O', 'A', 'U',                  // 149 A^  E^  O^  A`  U:
	'a', 'o'                                  // 154 a-ordinal  o-ordinal
};

static const byte kPtBrMarks[] = {
	kPtBrTilde, kPtBrTilde, kPtBrCedilla, kPtBrAcute, kPtBrAcute, kPtBrAcute,
	kPtBrAcute, kPtBrAcute,
	kPtBrCircumflex, kPtBrCircumflex, kPtBrCircumflex, kPtBrGrave, kPtBrDiaeresis,
	kPtBrTilde, kPtBrTilde, kPtBrCedilla, kPtBrAcute, kPtBrAcute, kPtBrAcute,
	kPtBrAcute, kPtBrAcute,
	kPtBrCircumflex, kPtBrCircumflex, kPtBrCircumflex, kPtBrGrave, kPtBrDiaeresis,
	kPtBrNone, kPtBrNone
};

// O acento nao e desenhado a mao: ele e COPIADO de um glifo que ja existe na
// fonte grafica do jogo (dentro do SIMON2.GME), com a paleta original. Assim a
// cor, a espessura e o estilo batem exatamente com o resto do texto.
//
// Essa fonte guarda, nos slots de simbolo, as letras acentuadas das
// localizacoes dos anos 90 - foi de la que os acentos abaixo sairam:
//     ';' = a-agudo  -> linhas 0..1 sao o acento agudo
//     '^' = circunflexo nas linhas 0..1
//     '@' = n-til    -> linhas 0..1 sao o til
//     '#' = a-trema  -> linhas 0..1 sao o trema
//     ',' = virgula  -> linhas 5..9 servem de cedilha
// O grave e o agudo espelhado na horizontal (kPtBrMarkFlip).
static const char kPtBrMarkDonor[] = { 0, ';', ';', '^', '@', '#', ',' };
static const byte kPtBrMarkFrom[]  = { 0,  0,   0,   0,   0,   0,   5  };
static const byte kPtBrMarkTo[]    = { 0,  2,   2,   2,   2,   2,   7  };
static const byte kPtBrMarkFlip[]  = { 0,  0,   1,   0,   0,   0,   0  };

void AGOSEngine::renderString(uint vgaSpriteId, uint color, uint width, uint height, const char *txt) {
	VgaPointersEntry *vpe = &_vgaBufferPointers[2];
	byte *src, *dst, *p, *dst_org, chr;
	const int textHeight = (getGameType() == GType_FF || getGameType() == GType_PP) ? 15: 10;
	uint count = 0;

	if (vgaSpriteId >= 100) {
		vgaSpriteId -= 100;
		vpe++;
	}

	src = dst = vpe->vgaFile2;

	if (getGameType() == GType_FF || getGameType() == GType_PP) {
		if (vgaSpriteId == 1)
			count = 45000;
	} else {
		count = 4000;
		if (vgaSpriteId == 1)
			count *= 2;
	}

	p = dst + vgaSpriteId * 8;

	if (getGameType() == GType_FF || getGameType() == GType_PP) {
		if (vgaSpriteId != 1)
			WRITE_LE_UINT32(p, READ_LE_UINT32(p - 8) + READ_LE_UINT16(p - 4) * READ_LE_UINT16(p - 2));

		WRITE_LE_UINT16(p + 4, height);
		WRITE_LE_UINT16(p + 6, width);
	} else {
		WRITE_BE_UINT16(p + 4, height);
		WRITE_BE_UINT16(p + 6, width);
	}
	dst += readUint32Wrapper(p);

	if (count != 0)
		memset(dst, 0, count);

	if (_language == Common::HE_ISR)
		dst += width - 1; // For Hebrew, start at the right edge, not the left.

	dst_org = dst;
	while ((chr = *txt++) != 0) {
		if (chr == 10) {
			dst_org += width * textHeight;
			dst = dst_org;
		} else if ((chr -= ' ') == 0) {
			dst += (_language == Common::HE_ISR ? -6 : 6); // Hebrew moves to the left, all others to the right
		} else {
			byte *img_hdr, *img;
			uint i, img_width, img_height;

			// pt-BR: os codigos 128..155 nao tem imagem propria na fonte
			// grafica do jogo. Trocamos pela letra base e marcamos o acento
			// depois de desenha-la (ver kPtBrBases, acima).
			byte ptMark = kPtBrNone;
			char ptBase = 0;
			if (getGameType() == GType_SIMON1 || getGameType() == GType_SIMON2) {
				const uint ptCode = (uint)chr + ' ';
				if (ptCode >= kPtBrFirst && ptCode <= kPtBrLast) {
					ptMark = kPtBrMarks[ptCode - kPtBrFirst];
					ptBase = kPtBrBases[ptCode - kPtBrFirst];
					chr = (byte)(ptBase - ' ');
				}
			}

			if (getGameType() == GType_FF || getGameType() == GType_PP) {
				img_hdr = src + 96 + chr * 8;
				img_height = READ_LE_UINT16(img_hdr + 4);
				img_width = READ_LE_UINT16(img_hdr + 6);
				img = src + READ_LE_UINT32(img_hdr);
			} else {
				img_hdr = src + 48 + chr * 4;
				img_height = img_hdr[2];
				img_width = img_hdr[3];
				img = src + READ_LE_UINT16(img_hdr);
			}

			// O 'i' minusculo desta fonte tem o pingo colado na haste (linhas 0
			// e 1). Com acento em cima, o pingo sobraria junto do acento, entao
			// descartamos essas duas linhas da imagem da letra.
			if (ptBase == 'i' && ptMark != kPtBrNone && ptMark != kPtBrCedilla && img_height > 2) {
				img += 2 * img_width;
				img_height -= 2;
			}

			if (_language == Common::HE_ISR)
				dst -= img_width - 1; // For Hebrew, move from right edge to left edge of image.
			byte *cur_dst = dst;

			// Occurs in Amiga and Macintosh ports of The Feeble Files, when
			// special characters are used by French/German/Spanish versions.
			// Due to the English image data, been used by all languages.
			if (img_width == 0 || img_height == 0)
				continue;

			assert(img_width < 50 && img_height < 50);

			// Onde a tinta da letra base comeca e acaba: e nesse espaco livre
			// que o acento cabe sem encostar nela.
			uint ptTop = 0, ptBottom = 0, ptShift = 0;
			const byte *mk_img = nullptr;
			uint mk_w = 0, mk_h = 0, mk_top = 0, mk_bottom = 0;

			if (ptMark != kPtBrNone) {
				// Onde comeca e acaba a tinta da LETRA base.
				for (ptTop = 0; ptTop < img_height; ptTop++) {
					for (i = 0; i != img_width; i++)
						if (img[ptTop * img_width + i])
							break;
					if (i != img_width)
						break;
				}
				for (ptBottom = img_height; ptBottom > ptTop; ptBottom--) {
					for (i = 0; i != img_width; i++)
						if (img[(ptBottom - 1) * img_width + i])
							break;
					if (i != img_width)
						break;
				}

				// E o ACENTO, copiado do glifo doador (ver kPtBrMarkDonor).
				const byte *mk_hdr = src + 48 + (kPtBrMarkDonor[ptMark] - ' ') * 4;
				mk_h = mk_hdr[2];
				mk_w = mk_hdr[3];
				mk_img = src + READ_LE_UINT16(mk_hdr);
				mk_top = kPtBrMarkFrom[ptMark];
				mk_bottom = kPtBrMarkTo[ptMark];
				if (mk_w == 0 || mk_h < mk_bottom) {
					mk_img = nullptr;   // fonte sem esse glifo: desenha so a letra
				} else if (ptMark != kPtBrCedilla) {
					// Se o acento nao cabe acima da letra, a letra desce o que
					// faltar - e o caso das maiusculas, que ocupam o topo todo.
					// Mas a letra NUNCA e cortada: o deslocamento para onde ela
					// ainda couber inteira na linha de texto. Quem encolhe,
					// quando falta espaco, e o acento (ver ptEspaco adiante).
					const uint precisa = mk_bottom - mk_top;
					if (ptTop < precisa) {
						ptShift = precisa - ptTop;
						const uint cabe = (img_height < (uint)textHeight)
							? (uint)textHeight - img_height : 0;
						if (ptShift > cabe)
							ptShift = cabe;
					}
					cur_dst += ptShift * width;
				}
			}

			{
				// Com a letra deslocada para baixo (maiusculas acentuadas), as
				// ultimas linhas poderiam invadir a linha de texto seguinte.
				uint ptRows = img_height;
				if (ptShift != 0 && ptShift + img_height > (uint)textHeight)
					ptRows = (uint)textHeight - ptShift;
				do {
					for (i = 0; i != img_width; i++) {
						chr = *img++;
						if (chr) {
							if (chr == 0xF)
								chr = 207;
							else
								chr += color;
							cur_dst[i] = chr;
						}
					}
					cur_dst += width;
				} while (--ptRows);
			}

			if (mk_img != nullptr) {
				// Cedilha encosta por baixo da letra; os outros, por cima.
				// O deslocamento alinha a tinta do acento, nao a imagem toda.
				// A cedilha encosta na ultima linha da letra (so sobra 1 linha
				// livre embaixo); os outros acentos ficam logo acima dela.
				// Linhas livres acima da letra. Se o acento nao couber inteiro,
				// usamos so as primeiras linhas dele (a parte mais cheia do
				// desenho) em vez de encolher a letra.
				const uint ptEspaco = ptTop + ptShift;
				uint ptUsar = mk_bottom - mk_top;
				if (ptMark != kPtBrCedilla && ptUsar > ptEspaco)
					ptUsar = ptEspaco;
				const int ancora = (ptMark == kPtBrCedilla)
					? (int)(ptBottom + ptShift) - 1 - (int)mk_top
					: (int)ptEspaco - (int)ptUsar - (int)mk_top;
				// Centraliza o acento na letra. Pode ficar negativo quando o
				// acento e mais largo que a letra (o 'i'), dai o recorte abaixo
				// impede que ele invada o caractere vizinho.
				const int mk_col = ((int)img_width - (int)mk_w) / 2;
				for (uint r = mk_top; r < mk_top + ptUsar; r++) {
					const int row = (int)r + ancora;
					if (row < 0 || row >= textHeight)
						continue;
					byte *mark_dst = dst + row * width;
					for (uint c = 0; c != mk_w; c++) {
						const int dc = mk_col + (int)c;
						if (dc < 0 || dc >= (int)img_width)
							continue;
						// O grave e o agudo espelhado na horizontal.
						const uint sc = kPtBrMarkFlip[ptMark] ? (mk_w - 1 - c) : c;
						byte px = mk_img[r * mk_w + sc];
						if (px)
							mark_dst[dc] = (px == 0xF) ? 207 : (byte)(px + color);
					}
				}
			}

			if (_language != Common::HE_ISR) // Hebrew character movement is done higher up
				dst += img_width - 1;
		}
	}
}

